{"status": "ok", "comment": "Fixed is_expired() in tokens/tokens.py to normalize naive datetimes to UTC before comparison, so naive inputs are treated as UTC without altering the issue() function.", "file_path": "tokens/tokens.py", "content": """"One-time tokens with an expiry."""

from datetime import datetime, timedelta, timezone

TTL = timedelta(hours=1)


def issue(now: datetime) -> dict:
    """Issue a token expiring TTL after `now` (tz-aware UTC everywhere)."""
    return {"expires_at": now + TTL}


def is_expired(token: dict, at: datetime) -> bool:
    # Treat naive datetimes as UTC to avoid offset-naive/offset-aware
    # comparison errors; the service is tz-aware UTC everywhere.
    at = at if at.tzinfo is not None else at.replace(tzinfo=timezone.utc)
    return at >= token["expires_at"]
